package org.apache.commons.math3.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector#unitize
 */
public class OpenMapRealVector_unitize_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testUnitizeWithValidVector() {
        // Create a vector with dimension 3: [3.0, 4.0, 0.0]
        // Norm should be sqrt(3^2 + 4^2) = 5.0
        OpenMapRealVector vector = new OpenMapRealVector(3);
        vector.setEntry(0, 3.0);
        vector.setEntry(1, 4.0);

        vector.unitize();

        // Expected values: [3/5, 4/5, 0/5] = [0.6, 0.8, 0.0]
        Assert.assertEquals(0.6, vector.getEntry(0), EPSILON);
        Assert.assertEquals(0.8, vector.getEntry(1), EPSILON);
        Assert.assertEquals(0.0, vector.getEntry(2), EPSILON);

        // Verify norm is now 1.0
        Assert.assertEquals(1.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testUnitizeWithSparseVector() {
        // Test with sparse entries to ensure iterator logic works
        OpenMapRealVector vector = new OpenMapRealVector(10);
        vector.setEntry(2, 10.0);
        vector.setEntry(8, 10.0);

        // Norm is sqrt(100 + 100) = sqrt(200) = 14.1421356237
        double norm = Math.sqrt(200.0);

        vector.unitize();

        Assert.assertEquals(10.0 / norm, vector.getEntry(2), EPSILON);
        Assert.assertEquals(10.0 / norm, vector.getEntry(8), EPSILON);
        Assert.assertEquals(1.0, vector.getNorm(), EPSILON);
    }

    @Test(expected = MathArithmeticException.class)
    public void testUnitizeWithZeroNormThrowsException() {
        // A vector of all zeros has norm 0.0
        OpenMapRealVector vector = new OpenMapRealVector(5);
        // Entries are 0.0 by default

        vector.unitize();
    }

    @Test(expected = MathArithmeticException.class)
    public void testUnitizeWithEmptyVectorThrowsException() {
        // A vector with dimension 0 might result in a 0 norm depending on implementation
        OpenMapRealVector vector = new OpenMapRealVector(0);

        vector.unitize();
    }

    @Test
    public void testUnitizeWithSingleElement() {
        OpenMapRealVector vector = new OpenMapRealVector(1);
        vector.setEntry(0, -5.0);

        vector.unitize();

        // Norm is 5.0, expected entry is -5.0 / 5.0 = -1.0
        Assert.assertEquals(-1.0, vector.getEntry(0), EPSILON);
        Assert.assertEquals(1.0, vector.getNorm(), EPSILON);
    }
}
